const DIMS = { "three-conditions.png": [2250,979], "policy-recall-by-model.png": [2250,1979],
  "explain-quality.png": [2250,1266], "model-quality.png": [2250,1420],
  "latency.png": [2250,733], "safety-layer-ablation.png": [2333,1250] };
function figure(file, capText, widthIn = 6.0) {
  const d = fs.readFileSync(path.join(PNG, file));
  const [dw, dh] = DIMS[file] || [2250, 1200];
  const w = widthIn * 96, ht = Math.round(w * dh / dw);
  return [ new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 200, after: 40 },
      children: [new ImageRun({ type: "png", data: d, transformation: { width: w, height: ht } })] }),
    cap(capText) ];
}
// Read width/height straight out of the PNG IHDR chunk, so screenshots keep
// their true aspect ratio without a hand-maintained dimension table.
function pngSize(buf) {
  return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) };
}

// A screenshot figure. Screenshots are wide, so they are scaled to the text
// width and capped in height to avoid pushing a caption onto the next page.
function shot(file, capText, widthIn = 6.1, maxHeightIn = 4.6) {
  const d = fs.readFileSync(path.join(SHOTS, file));
  const { w: dw, h: dh } = pngSize(d);
  let w = widthIn * 96, ht = Math.round(w * dh / dw);
  if (ht > maxHeightIn * 96) { ht = Math.round(maxHeightIn * 96); w = Math.round(ht * dw / dh); }
  return [
    new Paragraph({
      alignment: AlignmentType.CENTER, spacing: { before: 200, after: 40 },
      children: [new ImageRun({
        type: "png", data: d,
        transformation: { width: Math.round(w), height: ht },
      })],
    }),
    cap(capText),
  ];
}

function table(rows, widths) {
  const total = 9360;
  const cols = widths || rows[0].map(() => Math.floor(total / rows[0].length));
  return new Table({ width: { size: total, type: WidthType.DXA }, columnWidths: cols,
    rows: rows.map((cells, ri) => new TableRow({ tableHeader: ri === 0,
      children: cells.map((c, ci) => new TableCell({
        width: { size: cols[ci], type: WidthType.DXA },
        shading: ri === 0 ? { type: ShadingType.CLEAR, fill: "E8EBF0" } : undefined,
        margins: { top: 60, bottom: 60, left: 90, right: 90 },
        children: [new Paragraph({ alignment: ci === 0 ? AlignmentType.LEFT : AlignmentType.CENTER,
          spacing: { after: 0, line: 250 },
          children: [new TextRun({ text: String(c), font: FONT, size: SM, bold: ri === 0 })] })] })) })) });
}
